 974→async fn start_stream(
 975→    State(state): State<Arc<AppState>>,
 976→    Json(payload): Json<StartStreamRequest>,
 977→) -> Result<Json<StreamInfo>, AppError> {
 978→    if payload.chain != "solana" {
 979→        return Err(AppError::bad_request(
 980→            "Streaming is currently only supported for solana",
 981→        ));
 982→    }
 983→
 984→    let grpc_url = state
 985→        .config
 986→        .solana_grpc_url
 987→        .as_deref()
 988→        .filter(|u| !u.is_empty())
 989→        .ok_or_else(|| {
 990→            AppError::bad_request("Solana gRPC URL not configured (set SOLANA_GRPC_URL)")
 991→        })?;
 992→
 993→    let _permit = state
 994→        .stream_semaphore
 995→        .clone()
 996→        .try_acquire_owned()
 997→        .map_err(|_| AppError::service_unavailable("Too many concurrent streams"))?;
 998→
 999→    let stream_id = Uuid::new_v4();
1000→    let cancel = CancellationToken::new();
1001→    let tx_count = Arc::new(std::sync::atomic::AtomicU64::new(0));
1002→    let last_slot = Arc::new(std::sync::atomic::AtomicU64::new(0));
1003→
1004→    let adapter = SolanaGrpcAdapter::new(grpc_url, state.config.solana_grpc_token.clone());
1005→    let (mut rx, grpc_handle) = adapter.stream_transactions();
1006→
1007→    let cancel_clone = cancel.clone();
1008→    let tx_count_clone = Arc::clone(&tx_count);
1009→    let last_slot_clone = Arc::clone(&last_slot);
1010→    let repo = state.repo.clone();
1011→    let state_clone = Arc::clone(&state);
1012→
1013→    tokio::spawn(async move {
1014→        let _permit = _permit;
1015→        let mut batch: Vec<Transaction> = Vec::new();
1016→        let mut last_flush = Instant::now();
1017→        const FLUSH_INTERVAL: Duration = Duration::from_secs(5);
1018→        const BATCH_SIZE: usize = 100;
1019→
1020→        loop {
1021→            tokio::select! {
1022→                _ = cancel_clone.cancelled() => {
1023→                    info!(stream_id = %stream_id, "Stream cancelled");
1024→                    break;
1025→                }
1026→                maybe_tx = rx.recv() => {
1027→                    match maybe_tx {
1028→                        Some(tx) => {
1029→                            if let Some(slot) = tx.raw_metadata.get("slot").and_then(|v| v.as_u64()) {
1030→                                last_slot_clone.store(slot, std::sync::atomic::Ordering::Relaxed);
1031→                            }
1032→                            batch.push(tx);
1033→                            tx_count_clone.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
1034→
1035→                            if batch.len() >= BATCH_SIZE || last_flush.elapsed() >= FLUSH_INTERVAL {
1036→                                if let Err(e) = repo.save_transactions(&batch).await {
1037→                                    error!(stream_id = %stream_id, error = %e, "Failed to save streamed transactions");
1038→                                }
1039→                                batch.clear();
1040→                                last_flush = Instant::now();
1041→                            }
1042→                        }
1043→                        None => {
1044→                            info!(stream_id = %stream_id, "gRPC stream channel closed");
1045→                            break;
1046→                        }
1047→                    }
1048→                }
1049→            }
1050→        }
1051→
1052→        if !batch.is_empty() {
1053→            if let Err(e) = repo.save_transactions(&batch).await {
1054→                error!(stream_id = %stream_id, error = %e, "Failed to flush final batch");
1055→            }
1056→        }
1057→
1058→        grpc_handle.abort();
1059→        state_clone.streams.write().await.remove(&stream_id);
1060→        info!(stream_id = %stream_id, "Stream removed from active set");
1061→    });
1062→
1063→    let entry = StreamEntry {
1064→        id: stream_id,
1065→        cancel: cancel.clone(),
1066→        started_at: Instant::now(),
1067→        tx_count: Arc::clone(&tx_count),
1068→        last_slot: Arc::clone(&last_slot),
1069→    };
1070→
1071→    let info = StreamInfo {
1072→        id: stream_id,
1073→        uptime_secs: 0,
1074→        transactions_ingested: 0,
1075→        last_slot: 0,
1076→    };
1077→
1078→    state.streams.write().await.insert(stream_id, entry);
1079→    info!(stream_id = %stream_id, "Stream started");
1080→
1081→    Ok(Json(info))
1082→}
