1084→async fn stop_stream(
1085→    State(state): State<Arc<AppState>>,
1086→    Path(stream_id): Path<Uuid>,
1087→) -> Result<Json<serde_json::Value>, AppError> {
1088→    let streams = state.streams.read().await;
1089→    let entry = streams
1090→        .get(&stream_id)
1091→        .ok_or_else(|| AppError::not_found(format!("Stream {} not found", stream_id)))?;
1092→    entry.cancel.cancel();
1093→    drop(streams);
1094→
1095→    Ok(Json(serde_json::json!({
