 552→
 553→    pub async fn get_matches_by_target(
 554→        &self,
 555→        target_id: Uuid,
 556→        limit: i64,
 557→        offset: i64,
 558→    ) -> anyhow::Result<Vec<(TargetMatch, RawTransaction)>> {
 559→        let rows = sqlx::query(
 560→            "SELECT \
 561→                 tm.id, tm.target_id, tm.raw_transaction_id, tm.match_reason, tm.matched_at, \
 562→                 rt.id AS rt_id, rt.network, rt.tx_hash, rt.timestamp, rt.block_number, \
 563→                 rt.raw_metadata, rt.source, rt.ingestion_run_id, rt.ingested_at \
 564→             FROM target_matches tm \
 565→             JOIN raw_transactions rt ON rt.id = tm.raw_transaction_id \
 566→             WHERE tm.target_id = $1 \
 567→             ORDER BY rt.timestamp DESC \
 568→             LIMIT $2 OFFSET $3",
 569→        )
 570→        .bind(target_id)
 571→        .bind(limit)
 572→        .bind(offset)
 573→        .fetch_all(self.pool())
 574→        .await?;
 575→
 576→        let mut results = Vec::with_capacity(rows.len());
 577→        for row in &rows {
 578→            let tm = TargetMatch {
 579→                id: row.try_get("id")?,
 580→                target_id: row.try_get("target_id")?,
 581→                raw_transaction_id: row.try_get("raw_transaction_id")?,
 582→                match_reason: row.try_get("match_reason")?,
 583→                matched_at: row.try_get("matched_at")?,
 584→            };
 585→            let rt = RawTransaction {
 586→                id: row.try_get("rt_id")?,
 587→                network: row.try_get("network")?,
 588→                tx_hash: row.try_get("tx_hash")?,
