    ) -> anyhow::Result<Vec<Network>> {
        let rows = sqlx::query(
            "SELECT id, chain_family::text, display_name, is_testnet, finality_model, block_time_ms \
             FROM networks WHERE chain_family = $1::chain_family_enum ORDER BY id",
