 141→/// Program-specific filter (Solana only).
 142→/// Per TARGET_MODEL.md Section 2.3.
 143→#[derive(Debug, Clone, Serialize, Deserialize)]
 144→pub struct ProgramFilterSpec {
 145→    /// Instruction discriminator bytes to match.
 146→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 147→    pub instruction_discriminators: Vec<String>,
 148→    /// Whether CPI invocations count as matches (default: true).
 149→    #[serde(default = "default_true")]
 150→    pub include_cpi: bool,
 151→}
 152→
 153→impl Default for ProgramFilterSpec {
 154→    fn default() -> Self {
 155→        Self {
 156→            instruction_discriminators: Vec::new(),
 157→            include_cpi: true,
 158→        }
 159→    }
 160→}
 161→
 162→fn default_true() -> bool {
 163→    true
 164→}
