        let spec = TopicFilterSpec {
            topics: vec![
                serde_json::json!("0xddf252ad"),
                serde_json::Value::Null,
                serde_json::json!(["0xaaa", "0xbbb"]),
            ],
            address_filter: vec!["0xusdc".to_string()],
